import{_ as i}from"./index-BAkwCzTZ.js";import{az as l}from"./@vue-De9RwyRn.js";import"./element-plus-CKJIAC2w.js";import"./lodash-es-Ceiv_TW4.js";import"./@vueuse-Ihwzeb_o.js";import"./@element-plus-B-y2LHuz.js";import"./async-validator-j0i5Y79Y.js";import"./@popperjs-DxtSUbXb.js";import"./@ctrl-DGnlsNIE.js";import"./dayjs-KsS9adaU.js";import"./memoize-one-BAtLgO95.js";import"./normalize-wheel-es-TzhA1irr.js";import"./@floating-ui-BQjuueHq.js";import"./pinia-Dndd2XNl.js";import"./crypto-js-B6L3KfD1.js";import"./vue-i18n-DB7lm_w-.js";import"./@intlify-D8hALvN4.js";import"./vue-router-DNsliMEH.js";import"./pinia-plugin-persistedstate-COWkwNh5.js";const s=i({},[["render",function(i,s){return s[0]||(s[0]=l('<div class="helpBoxTop">一、显示设置</div><div class="helpDesText" style="margin-top:8px;"> 通过拖动进度条调整预览面面的亮度、对比度，饱和度和锐度，也可以设置进度条后面的数值。 </div><ul><li> 图像调节：通过拖动进度条调整预览画面的亮度、对比度、饱和度和锐度，也可以设置进度条后面的数值。 <ul style="list-style-type:circle;"><li>亮度：画面的明亮程度。</li><li>对比度：画面中明暗区域最亮的白和最暗的黑之间的对比程度。</li><li>饱和度：画面中色彩的鲜艳程度，饱和度越高，画面越鲜艳。</li></ul></li><li> 曝光：可设置曝光时间，曝光时间越长进的光越多，适合光线条件较差的情况，曝光时间短则适合光线较好的情况。 </li><li> 日夜转换：支持选择“白天”、“夜晚”、“自动”、“定时切换”和“报警输入触发”。 <ul style="list-style-type:circle;"><li>白天：图像为彩色。</li><li>夜晚：图像为黑白。</li><li>自动：设备根据外界环境亮度自动控制白天和夜晚的模式。</li><li> 定时切换：请设置白天的开始时间和结束时间，在该时间段内，摄像机将自动使用白天模式；在该时间段外，摄像机将自动使用夜晚模式。 </li><li> 报警输入触发：触发状态可选为“白天”或“夜晚”。若触发状态为“夜晚”，当报警输入未触发时，摄像机为白天状态；当报警输入触发时，摄像机切换到夜晚状态。 </li></ul></li><li> 背光 <ul style="list-style-type:circle;"><li> 背光补偿：当图像背景较亮时，开启背光补偿可有效解决由于曝光不足造成前景目标发暗问题。 </li><li> 宽动态：当在强光源（日光、灯具或反光等）照射下的高亮度区域与阴影、逆光等相对亮度较低的区域在监控画面中同时存在时，您可以开启宽动态功能来看清监控画面。 </li><li> 强光抑制：画面存在强光点时，开启此功能，可以对强光点进行适当抑制，使其它区域获得一定的补偿以获得更清晰的图像。该功能最常用于夜间。 </li></ul></li><li>图像增强：可选择普通模式和专家模式。</li><li> 降噪等级：普通模式下可设置。降噪等级即降低图像噪点的级别，对空域降噪级别和时域降噪级别进行联动调整。数值越大，代表降噪能力越强，噪点越少 </li><li> 空域降噪级别：专家模式下可设置。针对单帧画面进行处理。数值越大，代表降噪能力越强，噪点越少。动态场景下可以考虑关闭。 </li><li> 时域降噪级别：专家模式下可设置。结合前后帧进行处理。数值越大，代表降噪能力越强，噪点越少。推荐保持默认值50。动态场景下建议保持在较小数值。 </li></ul><div class="helpBoxTop">二、OSD设置</div><div class="helpDesText" style="margin-top:8px;"> OSD是指显示在监控画面的信息。您可勾选需要显示的OSD信息，此时您可拖动预览画面上OSD红色方框到想要显示的位置。同时您也可以修改预览画面上显 示的通道名称、时间及日期的格式 </div><div class="helpDesText helpBold" style="margin-top:8px;"> 说明：时间格式“24小时制”、“12小时制”可选。 </div><ul><li> 字符叠加：将字符叠加在图像画面上。先将对应的字符序号打勾，然后在字符内容栏中输入所需的字符，即可预览图像中显示输入的字符。 </li><li>OSD属性：在下拉框中选择设置OSD是否透明、是否闪烁。</li></ul><div class="helpBoxTop">三、视频遮盖</div><div class="helpDesText" style="margin-top:8px;"> 视频遮盖是指将监控图像中敏感的区域遮盖，不在图像中显示。 </div><ul><li>勾选 “启用视频遮盖”。</li><li> 单击“绘制区域”，在画面中单击鼠标左键并拖动鼠标，然后松开鼠标左键，即完成一个区域的绘制。 </li><li>在画面中最多可以绘制4个区域，当区域绘制完成后，单击“停止绘制”，结束区域绘制。</li><li>单击“清除全部”可以清除绘制的所有区域,一个监控图像中最多可以绘制4个区域。</li></ul>',10))}]]);export{s as default};
